async fn main() {
    let mut interval = time::interval(Duration::from_millis(100));

    interval.tick().await;

    time::sleep(Duration::from_millis(50)).await;
    interval.reset();

    interval.tick().await;
    interval.tick().await;

    // approximately 250ms have elapsed.
}

