use bitflags::{bitflags, bitflags_match};

bitflags! {
    #[derive(PartialEq)]
    struct Flags: u8 {
        const A = 1 << 0;
        const B = 1 << 1;
        const C = 1 << 2;
    }
}

let flags = Flags::A | Flags::B;

bitflags_match!(flags, {
    Flags::A | Flags::B => println!("A and/or B are set"),
    _ => println!("neither A nor B are set"),
})

